--
-- Table structure for table `order`
--

CREATE TABLE `order` (
  `orderID` varchar(20) NOT NULL,
  `orderDate` date NOT NULL,
  `userID` varchar(10) NOT NULL,
  `status` enum('Pending','Shipped','Delivered','Cancelled') NOT NULL,
  `shipping_method` varchar(50) NOT NULL,
  `subtotal` double NOT NULL,
  `shipping_fee` double NOT NULL,
  `discount` double NOT NULL,
  `total` decimal(10,2) NOT NULL,
  `shipAdd` text NOT NULL,
  `payID` varchar(20) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `order`
--
DELIMITER $$
CREATE TRIGGER `trg_order_id` BEFORE INSERT ON `order` FOR EACH ROW BEGIN
    DECLARE today_prefix VARCHAR(20);
    DECLARE last_id VARCHAR(20);
    DECLARE seq INT;

    -- Step 1: today's prefix
    SET today_prefix = CONCAT('ORD', DATE_FORMAT(CURDATE(), '%Y%m%d'));

    -- Step 2: find the last code for today
    SELECT orderID
    INTO last_id
    FROM `order`
    WHERE orderID LIKE CONCAT(today_prefix, '%')
    ORDER BY orderID DESC
    LIMIT 1;

    -- Step 3: calculate next sequence
    IF last_id IS NULL THEN
        SET seq = 1;
    ELSE
        SET seq = CAST(SUBSTRING(last_id, -4) AS UNSIGNED) + 1;
    END IF;

    -- Step 4: set new code
    SET NEW.orderID = CONCAT(today_prefix, LPAD(seq, 4, '0'));
END
$$
DELIMITER ;

