--
-- Table structure for table `payment`
--

CREATE TABLE `payment` (
  `payID` varchar(20) NOT NULL,
  `payMethod` enum('TNG','DuitNow','COD','Credit/Debit Card') NOT NULL,
  `payStatus` enum('Success','Failed','Pending') NOT NULL,
  `payDate` datetime NOT NULL,
  `amount` decimal(10,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `payment`
--
DELIMITER $$
CREATE TRIGGER `trg_payment_id` BEFORE INSERT ON `payment` FOR EACH ROW BEGIN
    DECLARE today_prefix VARCHAR(20);
    DECLARE last_id VARCHAR(20);
    DECLARE seq INT;

    -- Step 1: today's prefix
    SET today_prefix = CONCAT('P', DATE_FORMAT(CURDATE(), '%Y%m%d'));

    -- Step 2: find the last code for today
    SELECT payID
    INTO last_id
    FROM payment
    WHERE payID LIKE CONCAT(today_prefix, '%')
    ORDER BY payID DESC
    LIMIT 1;

    -- Step 3: calculate next sequence
    IF last_id IS NULL THEN
        SET seq = 1;
    ELSE
        SET seq = CAST(SUBSTRING(last_id, -4) AS UNSIGNED) + 1;
    END IF;

    -- Step 4: set new code
    SET NEW.payID = CONCAT(today_prefix, LPAD(seq, 4, '0'));
END
$$
DELIMITER ;

