CREATE TRIGGER `before_user_insert` BEFORE INSERT ON `user` FOR EACH ROW BEGIN
    DECLARE nextID INT;

    -- Get numeric part after the 'U' and find the max
    SELECT COALESCE(MAX(CAST(SUBSTRING(userID, 2) AS UNSIGNED)), 0) + 1
    INTO nextID
    FROM `user`;

    -- Format as 'U00001', 'U00002', etc.
    SET NEW.userID = CONCAT('U', LPAD(nextID, 5, '0'));
END
$$
